import { existsSync, readFileSync, realpathSync, statSync } from "node:fs";
import { isAbsolute, relative, resolve, sep } from "node:path";
import { type DiagnosticCheck, parseDiagnostics } from "./diagnostics/config.js";
import { normalizeRequiredChecks } from "./verification-policy.js";

export const CONFIG_FILE = ".project-aware-qa.json";
export interface BehaviorCheck {
	id: string;
	/** Argument vector, executed without a shell. Assertions belong to this test. */
	command: string[];
	cwd: string;
	surfaceIds: string[];
	requiredEnv: string[];
	/** Exact repo-relative outputs generated by this invocation, including Playwright traces. */
	artifacts: string[];
	/** Optional fresh Playwright JSON report; rejects zero, flaky, skipped or failed tests. */
	playwrightReport?: string;
}
export interface Suppression {
	surfaceId: string;
	gap: string;
	owner: string;
	reason: string;
	/** Inclusive UTC calendar day. */
	expires: string;
}
export interface TeamConfig {
	version: 1;
	/** Consumer root -> dependency roots, including non-Node shared directories. */
	dependencies: Record<string, string[]>;
	policy: { requiredChecks: string[]; failOnIncomplete: boolean; failOnNewHighRisk: boolean };
	baseline?: string;
	suppressions: Suppression[];
	behaviorChecks: BehaviorCheck[];
	diagnostics?: DiagnosticCheck[];
}

function object(value: unknown, at: string, keys: string[]): Record<string, unknown> {
	if (!value || typeof value !== "object" || Array.isArray(value))
		throw new Error(`${at} must be an object`);
	const result = value as Record<string, unknown>;
	for (const key of Object.keys(result))
		if (!keys.includes(key)) throw new Error(`Unknown ${at} field: ${key}`);
	return result;
}
function text(value: unknown, at: string): string {
	if (typeof value !== "string" || !value.trim() || /[\0\r\n]/.test(value))
		throw new Error(`${at} must be a nonempty single-line string`);
	return value;
}
function strings(value: unknown, at: string): string[] {
	if (value === undefined) return [];
	if (!Array.isArray(value)) throw new Error(`${at} must be an array`);
	return [...new Set(value.map((item) => text(item, at)))];
}
function boolean(value: unknown, at: string): boolean {
	if (value === undefined) return false;
	if (typeof value !== "boolean") throw new Error(`${at} must be a boolean`);
	return value;
}
export function repoPath(value: string): string {
	if (value === "." || value === "") return "";
	if (
		isAbsolute(value) ||
		/[\\\0\r\n:*?]/.test(value) ||
		value.split("/").some((part) => !part || part === "." || part === "..")
	)
		throw new Error(`Expected a normalized repo-relative path: ${JSON.stringify(value)}`);
	return value;
}
/** Resolve only bounded existing inputs inside the repository, including symlink targets. */
export function localInput(root: string, path: string, maxBytes = 4 * 1024 * 1024): string {
	const resolved = realpathSync(resolve(root, repoPath(path)));
	const rel = relative(realpathSync(root), resolved);
	if (isAbsolute(rel) || rel === ".." || rel.startsWith(`..${sep}`))
		throw new Error(`Input leaves project root: ${path}`);
	const stat = statSync(resolved);
	if (!stat.isFile() || stat.size > maxBytes)
		throw new Error(`Input is not a bounded file: ${path}`);
	return resolved;
}
export function readTeamConfig(root: string): TeamConfig {
	const defaults: TeamConfig = {
		version: 1,
		dependencies: {},
		policy: { requiredChecks: [], failOnIncomplete: false, failOnNewHighRisk: false },
		suppressions: [],
		behaviorChecks: [],
		diagnostics: [],
	};
	if (!existsSync(resolve(root, CONFIG_FILE))) return defaults;
	const data = object(
		JSON.parse(readFileSync(localInput(root, CONFIG_FILE), "utf8")),
		CONFIG_FILE,
		[
			"version",
			"dependencies",
			"policy",
			"baseline",
			"suppressions",
			"behaviorChecks",
			"diagnostics",
		],
	);
	if (data.version !== 1) throw new Error(`${CONFIG_FILE} version must be 1`);
	if (data.dependencies !== undefined) {
		if (
			!data.dependencies ||
			typeof data.dependencies !== "object" ||
			Array.isArray(data.dependencies)
		)
			throw new Error("dependencies must map consumer roots to dependency roots");
		defaults.dependencies = Object.fromEntries(
			Object.entries(data.dependencies).map(([consumer, deps]) => [
				repoPath(consumer),
				strings(deps, "dependencies").map(repoPath),
			]),
		);
		if (Object.keys(defaults.dependencies).length !== Object.keys(data.dependencies).length)
			throw new Error("Duplicate normalized dependency roots");
	}
	if (data.policy !== undefined) {
		const policy = object(data.policy, "policy", [
			"requiredChecks",
			"failOnIncomplete",
			"failOnNewHighRisk",
		]);
		defaults.policy = {
			requiredChecks: normalizeRequiredChecks(
				strings(policy.requiredChecks, "policy.requiredChecks"),
			),
			failOnIncomplete: boolean(policy.failOnIncomplete, "policy.failOnIncomplete"),
			failOnNewHighRisk: boolean(policy.failOnNewHighRisk, "policy.failOnNewHighRisk"),
		};
	}
	if (data.baseline !== undefined) defaults.baseline = repoPath(text(data.baseline, "baseline"));
	for (const field of ["suppressions", "behaviorChecks"] as const)
		if (data[field] !== undefined && !Array.isArray(data[field]))
			throw new Error(`${field} must be an array`);
	defaults.suppressions = ((data.suppressions ?? []) as unknown[]).map((value) => {
		const entry = object(value, "suppression", ["surfaceId", "gap", "owner", "reason", "expires"]);
		const suppression = Object.fromEntries(
			Object.entries(entry).map(([key, value]) => [key, text(value, `suppression.${key}`)]),
		) as unknown as Suppression;
		for (const key of ["surfaceId", "gap", "owner", "reason", "expires"] as const)
			text(suppression[key], `suppression.${key}`);
		if (
			!/^\d{4}-\d{2}-\d{2}$/.test(suppression.expires) ||
			!Number.isFinite(Date.parse(suppression.expires)) ||
			new Date(suppression.expires).toISOString().slice(0, 10) !== suppression.expires
		)
			throw new Error("suppression.expires must be a real YYYY-MM-DD date");
		return suppression;
	});
	const seen = new Set<string>();
	defaults.behaviorChecks = ((data.behaviorChecks ?? []) as unknown[]).map((value) => {
		const entry = object(value, "behaviorCheck", [
			"id",
			"command",
			"cwd",
			"surfaceIds",
			"requiredEnv",
			"artifacts",
			"playwrightReport",
		]);
		const id = text(entry.id, "behaviorCheck.id");
		if (!/^[a-z0-9][a-z0-9-]*$/.test(id) || seen.has(id))
			throw new Error(`Invalid or duplicate behavior check id: ${id}`);
		seen.add(id);
		// Repeated argv entries must retain their meaning.
		if (!Array.isArray(entry.command) || !entry.command.length)
			throw new Error(`behaviorCheck ${id} requires a command argument array`);
		const command = entry.command.map((arg) => text(arg, "behaviorCheck.command"));
		const surfaceIds = strings(entry.surfaceIds, "behaviorCheck.surfaceIds");
		if (!surfaceIds.length) throw new Error(`behaviorCheck ${id} requires explicit surfaceIds`);
		const requiredEnv = strings(entry.requiredEnv, "behaviorCheck.requiredEnv");
		if (requiredEnv.some((name) => !/^[A-Za-z_][A-Za-z0-9_]*$/.test(name)))
			throw new Error("requiredEnv must contain environment variable names, never values");
		return {
			id,
			command,
			cwd: repoPath(entry.cwd === undefined ? "" : text(entry.cwd, "behaviorCheck.cwd")),
			surfaceIds,
			requiredEnv,
			artifacts: strings(entry.artifacts, "behaviorCheck.artifacts").map(repoPath),
			playwrightReport:
				entry.playwrightReport === undefined
					? undefined
					: repoPath(text(entry.playwrightReport, "behaviorCheck.playwrightReport")),
		};
	});
	defaults.diagnostics = parseDiagnostics(data.diagnostics);
	return defaults;
}
